'use strict';
/**
 * PMD_V153_STAGED_DEPLOY_RUNTIME_QA
 * Reproduce the folder layout generated by the owner-facing --check script.
 * Unlike source-only unit tests, this catches accidentally omitted helper
 * files before another live VPS dry run is requested.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const child = require('node:child_process');

const installer = fs.readFileSync('scripts/pmd-device-fleet-v150-safe-deploy.sh', 'utf8');
test('installer stages Python helper and pinned fixture BEFORE invoking the isolated suite', () => {
  const marker = installer.indexOf('PMD_V153_DEPLOY_TEST_STAGE_HELPER');
  const copy = installer.indexOf('cp -- "$HELPER" "$STAGED/scripts/pmd-settings-app-link-v151.py"');
  const check = installer.indexOf('cmp -s -- "$HELPER" "$STAGED/scripts/pmd-settings-app-link-v151.py"');
  const fixture = installer.indexOf('git show "$FIX:app/admin/views/pmdsettings/index.blade.php" > "$STAGED/tests/pmd-settings-v150-fixture.blade.php"');
  const run = installer.indexOf('PMD_SETTINGS_TEST_FIXTURE=tests/pmd-settings-v150-fixture.blade.php');
  assert.ok(marker > 0 && copy > marker && check > copy, 'Reviewed Settings helper must be staged and verified');
  assert.ok(fixture > check && run > fixture, 'Canonical fixture must exist before Node tests');
  assert.ok(installer.includes('V151 SETTINGS + FLEET DRY RUN: PASS'));
  assert.ok(installer.includes('if [[ "$MODE" == --check ]]; then'));
  assert.ok(installer.includes('cmp -s "$ORIGINAL/$f" "$REVERSED/$f"'));
});
test('VPS-style staged folder executes all 11 contracts without ENOENT', (t) => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'pmd-v153-real-stage-'));
  t.after(() => fs.rmSync(tmp, {force: true, recursive: true}));
  const files = [
    'app/admin/views/pmdsettings/index.blade.php',
    'app/admin/views/pmddevices/index.blade.php',
    'app/admin/controllers/Pmddevices.php',
    'app/Services/PmdDevicePlatformService.php',
    'app/admin/assets/js/pmd-device-fleet-v150.js',
    'app/admin/assets/css/pmd-device-fleet-v150.css',
    'scripts/pmd-settings-app-link-v151.py',
    'tests/pmd-device-fleet-v150.test.cjs',
    'tests/pmd-device-fleet-v150-runtime.test.cjs',
    'tests/pmd-settings-app-link-v151.test.cjs'
  ];
  for (const name of files) {
    const dest = path.join(tmp, name);
    fs.mkdirSync(path.dirname(dest), {recursive: true});
    fs.copyFileSync(name, dest);
  }
  const canonical = path.join(tmp, 'tests/pmd-settings-v150-fixture.blade.php');
  fs.copyFileSync('app/admin/views/pmdsettings/index.blade.php', canonical);
  // Nested Node test runners inherit NODE_TEST_CONTEXT from the outer runner.
  // Remove it so this subprocess runs a complete standalone TAP suite rather
  // than attempting to forward its output over an absent test IPC channel.
  const nestedEnv = {...process.env,
    PMD_SETTINGS_TEST_FIXTURE: 'tests/pmd-settings-v150-fixture.blade.php'};
  delete nestedEnv.NODE_TEST_CONTEXT;
  const result = child.spawnSync(process.execPath, [
    '--test',
    'tests/pmd-device-fleet-v150.test.cjs',
    'tests/pmd-device-fleet-v150-runtime.test.cjs',
    'tests/pmd-settings-app-link-v151.test.cjs'
  ], {
    cwd: tmp,
    encoding: 'utf8',
    env: nestedEnv,
    timeout: 60000
  });
  assert.equal(result.error, undefined, String(result.error));
  assert.equal(result.status, 0, [result.stdout, result.stderr].join('\n').slice(-12000));
  assert.match(result.stdout, /# pass 11\b/);
  assert.match(result.stdout, /# fail 0\b/);
});
